  if (err) {
    console.error("Error opening database:", err);
  } else {
    console.log("✅ Connected to SQLite database");

    // Create tables with updated schema
    db.run(
      `CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      aadhaar_number TEXT UNIQUE NOT NULL,
      phone_number TEXT NOT NULL,
      otp TEXT NOT NULL,
      face_image TEXT,
      fingerprint_image TEXT,
      fingerprint_template TEXT,
      ip_address TEXT,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )`,
      (err) => {
        if (err) {
          console.error("Error creating users table:", err);
        } else {
          console.log("✅ Users table checked/created");

          // Check if fingerprint_template column exists, if not add it
          db.get("PRAGMA table_info(users)", (err, rows) => {
            if (err) {
              console.error("Error checking table schema:", err);
              return;
            }

            const hasFingerprintTemplate = rows.some(
              (row) => row.name === "fingerprint_template"
            );

            if (!hasFingerprintTemplate) {
              console.log(
                "🔄 Adding fingerprint_template column to users table..."
              );
              db.run(
                "ALTER TABLE users ADD COLUMN fingerprint_template TEXT",
                (err) => {
                  if (err) {
                    console.error(
                      "❌ Error adding fingerprint_template column:",
                      err
                    );
                  } else {
                    console.log(
                      "✅ Successfully added fingerprint_template column"
                    );
                  }
                }
              );
            } else {
              console.log("✅ fingerprint_template column already exists");
            }
          });
        }
      }
    );

    db.run(`CREATE TABLE IF NOT EXISTS admin_users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      phone_number TEXT NOT NULL,
      secret_code TEXT NOT NULL,
      password TEXT NOT NULL
    )`);

    // Insert default admin user
    const defaultAdmin = {
      email: "admin@evoting.com",
      phone: "9876543210",
      secretCode: "ADMIN123",
      password: bcrypt.hashSync("admin123", 10),
    };

    db.get(
      "SELECT * FROM admin_users WHERE email = ?",
      [defaultAdmin.email],
      (err, row) => {
        if (!row) {
          db.run(
            "INSERT INTO admin_users (email, phone_number, secret_code, password) VALUES (?, ?, ?, ?)",
            [
              defaultAdmin.email,
              defaultAdmin.phone,
              defaultAdmin.secretCode,
              defaultAdmin.password,
            ]
          );
          console.log("✅ Default admin user created");
        }
      }
    );
  }
});

// Configure multer for file uploads
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = "uploads/";
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueName =
      Date.now() +
      "-" +
      Math.round(Math.random() * 1e9) +
      path.extname(file.originalname);
    cb(null, uniqueName);
  },
});

const upload = multer({
  storage: storage,
  limits: { fileSize: 10 * 1024 * 1024 },
});

// PB1000 Fingerprint Scanner Simulation
class PB1000FingerprintScanner {
  constructor() {
    this.isConnected = false;
    this.init();
  }

  async init() {
    try {
      // Simulate hardware detection
      console.log("🔍 Searching for PB1000 Fingerprint Scanner...");
      setTimeout(() => {
        this.isConnected = false; // Set to false for simulation
        console.log(
          "⚠️ PB1000 Fingerprint Scanner not found. Using simulated mode."
