    } catch (error) {
      console.error("❌ Error initializing fingerprint scanner:", error);
      this.isConnected = false;
    }
  }

  // Capture fingerprint image
  captureFingerprint() {
    return new Promise((resolve, reject) => {
      console.log("👆 Simulating fingerprint capture...");

      // Simulate capture process
      setTimeout(() => {
        const simulatedImage = `fingerprint_${Date.now()}.bmp`;
        const template = `template_${Date.now()}_${Math.random()
          .toString(36)
          .substr(2, 9)}`;

        resolve({
          success: true,
          image: simulatedImage,
          template: template,
          message: "Fingerprint captured successfully (simulated mode)",
        });
      }, 2000);
    });
  }

  // Verify fingerprint against stored templates
