    WHERE name = ? OR aadhaar_number = ? OR phone_number = ? OR otp = ?
  `;

  db.all(query, [name, aadhaarNumber, phoneNumber, otp], (err, rows) => {
    if (err) {
      return callback(err, null);
    }

    if (rows.length > 0) {
      const duplicates = [];

      rows.forEach((row) => {
        if (row.name === name) {
          duplicates.push(`Name "${name}"`);
        }
        if (row.aadhaar_number === aadhaarNumber) {
          duplicates.push(`Aadhaar Number "${aadhaarNumber}"`);
        }
        if (row.phone_number === phoneNumber) {
          duplicates.push(`Phone Number "${phoneNumber}"`);
        }
        if (row.otp === otp) {
          duplicates.push(`OTP "${otp}"`);
        }
      });

      // Remove duplicates from the duplicates array
      const uniqueDuplicates = [...new Set(duplicates)];

      return callback(null, {
        isDuplicate: true,
        duplicateFields: uniqueDuplicates,
        existingRecords: rows,
      });
    }

    callback(null, { isDuplicate: false });
  });
};

