// User Verification with Duplicate Check
app.post(
  "/api/verify-user",
  upload.fields([
    { name: "faceImage", maxCount: 1 },
    { name: "fingerprintImage", maxCount: 1 },
  ]),
  (req, res) => {
    try {
      const { name, aadhaarNumber, phoneNumber, otp, fingerprintTemplate } =
        req.body;

      const userData = {
        name,
        aadhaarNumber,
        phoneNumber,
        otp,
        faceImage: req.files["faceImage"]
          ? req.files["faceImage"][0].filename
          : null,
        fingerprintImage: req.files["fingerprintImage"]
          ? req.files["fingerprintImage"][0].filename
          : null,
        fingerprintTemplate: fingerprintTemplate || null,
        ipAddress: req.ip || req.connection.remoteAddress,
      };

      console.log("📝 User verification data:", {
        name: userData.name,
        aadhaar: userData.aadhaarNumber,
        phone: userData.phoneNumber,
        hasFaceImage: !!userData.faceImage,
        hasFingerprintImage: !!userData.fingerprintImage,
        hasFingerprintTemplate: !!userData.fingerprintTemplate,
      });

      // First check for duplicate votes
      checkDuplicateVote(userData, (err, duplicateResult) => {
        if (err) {
          console.error("Error checking duplicates:", err);
          return res.status(500).json({
            success: false,
            message: "Error checking for duplicate votes",
          });
        }

        if (duplicateResult.isDuplicate) {
          const duplicateFields = duplicateResult.duplicateFields.join(", ");
          return res.status(400).json({
            success: false,
            message: `Voter has already voted! Duplicate found in: ${duplicateFields}`,
            duplicateFields: duplicateResult.duplicateFields,
            existingRecords: duplicateResult.existingRecords,
          });
        }

        // If no duplicates, proceed with insertion
        const query = `
          INSERT INTO users (name, aadhaar_number, phone_number, otp, face_image, fingerprint_image, fingerprint_template, ip_address) 
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `;

        const params = [
          userData.name,
          userData.aadhaarNumber,
          userData.phoneNumber,
          userData.otp,
          userData.faceImage,
          userData.fingerprintImage,
          userData.fingerprintTemplate,
          userData.ipAddress,
        ];

        console.log("💾 Inserting user data into database...");

        db.run(query, params, function (err) {
          if (err) {
            console.error("❌ Database insertion error:", err);

            if (err.code === "SQLITE_CONSTRAINT_UNIQUE") {
              return res.status(400).json({
                success: false,
                message: "Aadhaar number already exists",
              });
            }

            // Handle missing column error
            if (err.message.includes("no column named fingerprint_template")) {
              console.log(
                "🔄 Database schema outdated. Adding missing column..."
              );

              // Add the missing column and retry
              db.run(
                "ALTER TABLE users ADD COLUMN fingerprint_template TEXT",
                (alterErr) => {
                  if (alterErr) {
                    return res.status(500).json({
                      success: false,
                      message:
                        "Database schema error. Please restart the application.",
                    });
                  }

                  // Retry insertion without fingerprint template
                  db.run(
                    `INSERT INTO users (name, aadhaar_number, phone_number, otp, face_image, fingerprint_image, ip_address) 
                   VALUES (?, ?, ?, ?, ?, ?, ?)`,
                    [
                      userData.name,
                      userData.aadhaarNumber,
                      userData.phoneNumber,
                      userData.otp,
                      userData.faceImage,
                      userData.fingerprintImage,
                      userData.ipAddress,
                    ],
                    function (retryErr) {
                      if (retryErr) {
                        return res.status(500).json({
                          success: false,
                          message: "Database error: " + retryErr.message,
                        });
                      }

                      // Update Excel file
                      updateExcelFile();

                      res.json({
                        success: true,
                        message: "User verification completed successfully!",
                        data: { ...userData, id: this.lastID },
                      });
                    }
                  );
                }
              );
              return;
            }

            return res.status(500).json({
              success: false,
              message: "Database error: " + err.message,
            });
          }

          // Update Excel file
          updateExcelFile();

          console.log(
            "✅ User verification data saved successfully. ID:",
            this.lastID
          );

          res.json({
            success: true,
            message: "User verification completed successfully!",
            data: { ...userData, id: this.lastID },
          });
        });
      });
    } catch (error) {
      console.error("❌ Verification error:", error);
      res.status(500).json({ success: false, message: error.message });
    }
  }
);

